int /* <=== vips_dzsave */ 
vips_dzsave( VipsImage *in, const char *name, ... )
{
	va_list ap;
	int result;

	va_start( ap, name );
	result = vips_call_split( "dzsave", ap, in, name ); 
	va_end( ap );

	return( result );
}

char * /* <=== im_getnextoption */ 
im_getnextoption( char **in )
{
        char *p;
        char *q;

        p = *in;
        q = p;

        if( !p || !*p )
                return( NULL );

	/* Find the next ',' not prefixed with a '\'. If the first character
	 * of p is ',', there can't be a previous escape character.
	 */
	for(;;) {
		if( !(p = strchr( p, ',' )) )
			break;
		if( p == q )
			break;
		if( p[-1] != '\\' )
			break;

		p += 1;
	}

        if( p ) {
                /* Another option follows this one .. set up to pick that out
                 * next time.
                 */
                *p = '\0';
                *in = p + 1;
        }
        else {
                /* This is the last one.
                 */
                *in = NULL;
        }

        if( strlen( q ) > 0 )
                return( q );
        else
                return( NULL );
}

typeDefs:
typedef enum {
	VIPS_FOREIGN_DZ_LAYOUT_DZ,
	VIPS_FOREIGN_DZ_LAYOUT_ZOOMIFY,
	VIPS_FOREIGN_DZ_LAYOUT_GOOGLE,
	VIPS_FOREIGN_DZ_LAYOUT_LAST
}

typedef enum {
	VIPS_FOREIGN_DZ_DEPTH_ONEPIXEL,
	VIPS_FOREIGN_DZ_DEPTH_ONETILE,
	VIPS_FOREIGN_DZ_DEPTH_ONE,
	VIPS_FOREIGN_DZ_DEPTH_LAST
}

typedef struct {
	VipsCompositeBase *composite;

	/* Full set of input regions, each made on the corresponding input
	 * image.
	 */
	VipsRegion **input_regions;

	/* We then vips_region_prepare_to() to one of this set of regions,
	 * each defined on the base image.
	 */
	VipsRegion **composite_regions;

	/* Number of input regions which intersect this request rect.
	 */
	int n;

	/* For each of @n above (inputs which intersect this request), the
	 * index of the input image we need. We can use this index to get the
	 * position, input region and composite region.
	 */
	int *enabled;

	/* For each enabled image, an input pointer.
	 */
	VipsPel **p;

}

